package control_flow.assigment_problems;
public class PrimeNumberChecker { public static void checkPrime(int number){if(number<=1){System.out.println("Not Prime");return;}boolean prime=true;for(int i=2;i<=number/2;i++)if(number%i==0){prime=false;break;}System.out.println(prime?"Prime":"Not Prime");} public static void main(String[] a){checkPrime(17);} }